  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.FrigateThreatResponseSystem_Instance_threatResponseProcess_threatQualification_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.Frigate_Threat_Response_Coordinator.ThreatQualification_threatResponseProcess_threatQualification_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_qualifiedThreatToAlertOut" ~> postContainer.api_qualifiedThreatToAlertOut.string
        updates = updates + s"${bridge_id}_Out_threatValidityToDefenseOut" ~> postContainer.api_threatValidityToDefenseOut.string
        updates = updates + s"${bridge_id}_Out_threatValidityToEscapeOut" ~> postContainer.api_threatValidityToEscapeOut.string
