      case scp_candidate.runtimemonitor.ObservationKind.FrigateThreatResponseSystem_Instance_threatResponseProcess_alertMemory_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.Frigate_Threat_Response_Coordinator.AlertMemory_threatResponseProcess_alertMemory_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_retainedAlert" ~> postContainer.retainedAlert.string
        updates = updates + s"${bridge_id}_Out_defenseAlertOut" ~> postContainer.api_defenseAlertOut.string
        updates = updates + s"${bridge_id}_Out_escapeAlertOut" ~> postContainer.api_escapeAlertOut.string
        updates = updates + s"${bridge_id}_Out_compositionAlertOut" ~> postContainer.api_compositionAlertOut.string
        updates = updates + s"${bridge_id}_Out_threatReportOut" ~> postContainer.api_threatReportOut.string
